+import { Redis } from "ioredis"
+import { createRedisClient } from "../config/redis.js"
+
+export type ActivityEntry = {
+  id: string
+  ts: string
+  type: "step_start" | "step_done" | "phase" | "note"
+  stepId?: number
+  phase?: string
+  message: string
+  meta?: Record<string, unknown>
+}
+
+export class ActivityStore {
+  private redis: Redis
+  private MAX = 100
+  private TTL = 60 * 60 * 24 * 7 // 7 days
+
+  constructor() {
+    this.redis = createRedisClient()
+  }
+
+  private key(taskId: string) {
+    return `activity:${taskId}`
+  }
+
+  async append(taskId: string, entry: ActivityEntry): Promise<void> {
+    const key = this.key(taskId)
+    const data = JSON.stringify(entry)
+    // push and trim
+    await this.redis.lpush(key, data)
+    await this.redis.ltrim(key, 0, this.MAX - 1)
+    await this.redis.expire(key, this.TTL)
+  }
+
+  async list(taskId: string, limit = 50): Promise<ActivityEntry[]> {
+    const key = this.key(taskId)
+    const raw = await this.redis.lrange(key, 0, Math.max(0, limit - 1))
+    return raw.map((r) => JSON.parse(r) as ActivityEntry)
+  }
+
+  async clear(taskId: string): Promise<void> {
+    await this.redis.del(this.key(taskId))
+  }
+}
+
+export const activityStore = new ActivityStore()
+
