+  /** Count tasks in `running` status older than given minutes by scanning recent index. */
+  async runningOverMinutes(minutes: number): Promise<number> {
+    const cutoff = Date.now() - minutes * 60 * 1000
+    const ids = await this.redis.zrangebyscore(this.INDEX_KEY, 0, cutoff)
+    let count = 0
+    for (const id of ids) {
+      const entry = await this.get(id)
+      if (entry && entry.status === 'running') count++
+    }
+    return count
+  }
+
   async saveMetrics(taskId: string, metrics: TaskMetricsSnapshot): Promise<void> {
     await this.redis.set(this.metricsKey(taskId), JSON.stringify(metrics), "EX", this.TTL)
   }
